<script>
(function(){function initRoleUi(){var sidebar=document.getElementById('sidebar'),menuBtn=document.getElementById('menuBtn');if(menuBtn&&sidebar&&!menuBtn.dataset.uiBound){menuBtn.dataset.uiBound='1';menuBtn.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();sidebar.classList.toggle('open')})}var themeBtn=document.getElementById('themeToggleBtn');if(themeBtn&&!themeBtn.dataset.uiBound){themeBtn.dataset.uiBound='1';var key='siberad-theme';function applyTheme(theme){if(theme==='light')document.documentElement.setAttribute('data-theme','light');else document.documentElement.removeAttribute('data-theme');themeBtn.setAttribute('aria-pressed',theme==='light'?'true':'false')}var saved='dark';try{saved=localStorage.getItem(key)||'dark'}catch(err){}applyTheme(saved);themeBtn.addEventListener('click',function(){var current=document.documentElement.getAttribute('data-theme')==='light'?'light':'dark',next=current==='light'?'dark':'light';try{localStorage.setItem(key,next)}catch(err){}applyTheme(next)})}var profileBtn=document.getElementById('profileMenuBtn'),profileDrop=document.getElementById('profileDropdown');if(profileBtn&&profileDrop&&!profileBtn.dataset.uiBound){profileBtn.dataset.uiBound='1';profileBtn.addEventListener('click',function(e){e.stopPropagation();profileDrop.classList.toggle('open')});document.addEventListener('click',function(e){if(!profileDrop.parentElement.contains(e.target))profileDrop.classList.remove('open')})}window.openProfileModal=window.openProfileModal||function(id){var overlay=document.getElementById('profileModalOverlay');if(!overlay)return;overlay.querySelectorAll('.profile-dropdown-view').forEach(function(view){view.style.display=view.id===id?'block':'none'});overlay.classList.add('open');if(profileDrop)profileDrop.classList.remove('open')};var closeProfile=document.getElementById('profileModalCloseBtn');if(closeProfile&&!closeProfile.dataset.uiBound){closeProfile.dataset.uiBound='1';closeProfile.addEventListener('click',function(){var overlay=document.getElementById('profileModalOverlay');if(overlay)overlay.classList.remove('open')})}}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',initRoleUi);else initRoleUi()})();
</script>
<script>
(function(){function normalisasiNamaLogAktivitas(){var table=document.getElementById('tblLogAktivitas');if(!table)return;var normalisasi={'BINMAT':'Binmat','BINFUNG':'Binfung','BINUM':'Binum','DIKLAT':'Diklat'};table.querySelectorAll('tbody tr').forEach(function(row){var cells=row.children;if(cells.length<2)return;var pengguna=cells[1],teks=pengguna.textContent;Object.keys(normalisasi).forEach(function(nama){teks=teks.replace(new RegExp('\\b'+nama+'\\b','g'),normalisasi[nama])});pengguna.textContent=teks})}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',normalisasiNamaLogAktivitas);else normalisasiNamaLogAktivitas()})();
</script>
<script>
(function(){function removeOnlyPreviewToolbar(frame){if(!frame)return;frame.style.overflowX='hidden';frame.style.overflowY='auto';var zoomToolbar=frame.querySelector('.lp-zoom-toolbar');if(zoomToolbar)zoomToolbar.remove();Array.prototype.slice.call(frame.children).forEach(function(child){if(child.classList.contains('lp-browser-bar')||child.classList.contains('lp-preview'))return;var text=(child.textContent||'').replace(/\s+/g,' ').trim().toLowerCase(),buttons=child.querySelectorAll?child.querySelectorAll('button'):[],hasOnlyFitButton=buttons.length===1&&(buttons[0].textContent||'').trim().toLowerCase()==='fit';if(text==='fit'||hasOnlyFitButton)child.remove()})}function setupLandingPreview(){document.querySelectorAll('.lp-browser-frame').forEach(function(frame){removeOnlyPreviewToolbar(frame);if(frame.dataset.previewToolbarGuard==='1')return;frame.dataset.previewToolbarGuard='1';var observer=new MutationObserver(function(){removeOnlyPreviewToolbar(frame)});observer.observe(frame,{childList:true,subtree:true})})}function blockRealLoginInPreview(frame){if(!frame)return;var iframe=frame.querySelector('#lpLiveLandingFrame');if(!iframe||iframe.dataset.previewLoginGuard==='1')return;iframe.dataset.previewLoginGuard='1';iframe.addEventListener('load',function(){try{var doc=iframe.contentDocument||iframe.contentWindow.document;if(!doc)return;doc.querySelectorAll('form').forEach(function(form){if(form.dataset.previewLoginBlocked==='1')return;form.dataset.previewLoginBlocked='1';form.addEventListener('submit',function(event){event.preventDefault();event.stopImmediatePropagation()},true)})}catch(error){}})}function init(){setupLandingPreview();document.querySelectorAll('.lp-browser-frame').forEach(blockRealLoginInPreview)}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();var rootObserver=new MutationObserver(init);rootObserver.observe(document.body,{childList:true,subtree:true});window.setTimeout(function(){rootObserver.disconnect()},5000)})();
</script>
<style>
.role-access-table-wrap{width:100%;overflow-x:auto;border:1px solid var(--border-soft);border-radius:14px;background:var(--panel);box-shadow:0 8px 28px rgba(15,23,42,.06)}.role-access-table{width:100%;border-collapse:separate;border-spacing:0;min-width:900px;table-layout:fixed}.role-access-table th{padding:13px 16px;text-align:left;background:var(--panel-alt);border-bottom:1px solid var(--border-soft);color:var(--text-muted);font-family:var(--mono);font-size:10px;font-weight:700;letter-spacing:.07em;text-transform:uppercase}.role-access-table td{padding:16px;border-bottom:1px solid var(--border-soft);vertical-align:top;background:var(--panel)}.role-access-table tbody tr:last-child td{border-bottom:0}.role-access-table tbody tr:hover td{background:var(--hover-tint)}.role-access-table th:nth-child(1),.role-access-table td:nth-child(1){width:20%}.role-access-table th:nth-child(2),.role-access-table td:nth-child(2){width:23%}.role-access-table th:nth-child(3),.role-access-table td:nth-child(3){width:42%}.role-access-table th:nth-child(4),.role-access-table td:nth-child(4){width:15%}.role-access-role{font-weight:700;color:var(--text);font-size:13px;line-height:1.4}.role-access-code{display:inline-flex;margin-top:6px;padding:4px 8px;border:1px solid var(--border-soft);border-radius:7px;background:var(--panel-alt);color:var(--gold-bright);font-family:var(--mono);font-size:9px;letter-spacing:.07em}.role-access-desc{margin:0;color:var(--text-muted);font-size:12px;line-height:1.55}.role-access-form{padding:0!important}.role-access-permissions{display:flex;flex-wrap:wrap;gap:8px 14px;margin:0 0 12px}.role-access-permission{display:inline-flex;align-items:center;gap:6px;color:var(--text-muted);font-size:11.5px;line-height:1.35;cursor:pointer}.role-access-permission input{margin:0;accent-color:var(--gold)}.role-access-save{white-space:nowrap}@media(max-width:900px){.role-access-table-wrap{border-radius:12px}.role-access-table{min-width:820px}}
</style>
<script>
(function(){function initRoleAccessTable(){var section=document.querySelector('[data-tab-panel="role-akses"]');if(!section||section.dataset.roleAccessTableReady==='1')return;var panels=Array.prototype.filter.call(section.children,function(el){return el.classList&&el.classList.contains('panel')});if(!panels.length)return;var rows=[];panels.forEach(function(panel){var head=panel.querySelector('.panel-head'),form=panel.querySelector('form');if(!head||!form)return;var title=head.querySelector('h3'),description=head.querySelector('p'),badge=title&&title.querySelector('.badge'),roleName=title?Array.prototype.filter.call(title.childNodes,function(n){return n.nodeType===3}).map(function(n){return n.textContent}).join(' ').trim():'',code=badge?badge.textContent.trim():'';var permissionWrap=form.querySelector('div[style*="flex-wrap"]');if(permissionWrap){permissionWrap.classList.add('role-access-permissions');permissionWrap.removeAttribute('style')}form.classList.add('role-access-form');Array.prototype.forEach.call(form.querySelectorAll('label'),function(label){label.classList.add('role-access-permission');label.removeAttribute('style')});var save=form.querySelector('button[type="submit"]');if(save)save.classList.add('role-access-save');rows.push({panel:panel,form:form,roleName:roleName,code:code,description:description?description.textContent.trim():'Tidak ada deskripsi.',permissionWrap:permissionWrap,save:save})});if(!rows.length)return;var wrap=document.createElement('div');wrap.className='role-access-table-wrap';var table=document.createElement('table');table.className='role-access-table';table.setAttribute('aria-label','Role dan hak akses');table.innerHTML='<thead><tr><th>Role / Satuan</th><th>Deskripsi</th><th>Hak Akses Modul</th><th>Aksi</th></tr></thead>';var tbody=document.createElement('tbody');rows.forEach(function(item,index){var tr=document.createElement('tr'),roleCell=document.createElement('td');roleCell.innerHTML='<div class="role-access-role"></div>'+(item.code?'<span class="role-access-code"></span>':'');roleCell.querySelector('.role-access-role').textContent=item.roleName;if(item.code)roleCell.querySelector('.role-access-code').textContent=item.code;var descCell=document.createElement('td'),desc=document.createElement('p');desc.className='role-access-desc';desc.textContent=item.description;descCell.appendChild(desc);var accessCell=document.createElement('td'),formId='role-access-form-'+index;item.form.id=formId;accessCell.appendChild(item.form);if(item.permissionWrap)item.form.appendChild(item.permissionWrap);var actionCell=document.createElement('td');if(item.save){item.save.setAttribute('form',formId);actionCell.appendChild(item.save)}tr.appendChild(roleCell);tr.appendChild(descCell);tr.appendChild(accessCell);tr.appendChild(actionCell);tbody.appendChild(tr)});table.appendChild(tbody);wrap.appendChild(table);rows.forEach(function(item){item.panel.remove()});section.appendChild(wrap);section.dataset.roleAccessTableReady='1'}function run(){if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',initRoleAccessTable,{once:true});else initRoleAccessTable()}run();document.addEventListener('click',function(e){var link=e.target.closest&&e.target.closest('[data-tab-link="role-akses"]');if(link)window.setTimeout(initRoleAccessTable,0)})})();
</script>
